            WHERE $scope AND m.deleted_at IS NULL $w ORDER BY m.id LIMIT ".($limit+1),$p);$more=count($rows)>$limit;if($more){array_pop($rows);}return['items'=>$rows,'nextCursor'=>$more?end($rows)['id']:null,'directory'=>$tree];}public function detail(Auth$a,string$id):array{$m=Access::material($a,$id);$m['author_name']=DB::one('SELECT display_name FROM users WHERE id=?',[$m['owner_user_id']])['display_name'];$m['subject_title']=$m['subject_id']?DB::one('SELECT title FROM subjects WHERE id=?',[$m['subject_id']])['title']:$m['course_title'];$m['group_code']=$m['group_id']?DB::one('SELECT canonical_code FROM academic_groups WHERE id=?',[$m['group_id']])['canonical_code']:null;$m['lessons']=DB::all('SELECT cm.id,cm.start_at,cm.end_at,cm.class_type FROM material_lessons ml JOIN class_meetings cm ON cm.id=ml.meeting_id WHERE ml.material_id=? ORDER BY cm.start_at',[$id]);if($m['visibility']==='group'&&($connection=DriveLibrary::connection($a))){$account=$connection['google_subject'];$receivesCopies=LibraryGroup::selected($a->user['id'])===$m['group_id']||$m['owner_user_id']===$a->user['id'];$m['files']=DB::all("SELECT f.id,f.original_name,f.mime_type,f.size_bytes,f.checksum_sha256,f.version,f.scan_status,f.created_at,
