l=DB::one('SELECT * FROM materials WHERE id=? AND deleted_at IS NULL FOR UPDATE',[$id])??throw new ApiError(404,'NOT_FOUND','Материал не найден');$title=array_key_exists('title',$r->body)?Input::text($r->body,'title'):$material['title'];$description=array_key_exists('description',$r->body)?Input::text($r->body,'description',50000,false):$material['description'];$category=$this->category($r->body['category']??$material['category']);DB::run('UPDATE materials SET title=?,description=?,category=?,updated_at=UTC_TIMESTAMP(6) WHERE id=?',[$title,$description,$category,$id]);Access::audit($a,'material.update','material',$id,$r->correlationId);return['updated'=>true,'id'=>$id];}public function upload(Auth$a,Request$r,string$id):array{$material=Access::material($a,$id,true);$files=Request::uploadedFiles();if(!$files||count($files)>20||isset($_FILES['file'],$_FILES['files'])){throw new ApiError(422,'UPLOAD_FAILED','Выберите от 1 до 20 файлов');}$validated=[];foreach($files as$file){if(in_array($file['error']??null,[UPLOAD_ERR_INI_SIZE,UPLOAD_ERR_FORM_SIZE],true)){throw new ApiError(413,'UPLOAD_LIMIT','Файл превышает лимит загрузки');}$temp=$file['tmp_name']??null;if(!is_string($file['name']??null)||($file['error']??null)!==UPLOAD_ERR_OK||!is_string($temp)||!is_uploaded_file($temp)){throw new ApiError(422,'UPLOAD_FAILED','Не удалось загрузить один из файлов');}$bytes=filesize($temp);if($bytes===false)throw new ApiError(503,'STORAGE','Не удалось определить размер файла');$name=mb_substr(basename(str_replace('\\','/',$file['name'])),0,240);$name=preg_replace('/[\x00-\x1F\x7F]/','_',$name)?:'download';$hash=hash_file('sha256',$temp);if($hash===false)throw new ApiError(503,'STORAGE','Не удалось прочитать загруженный файл');$validated[]=[$temp,$name,$bytes,$hash];}DB::one('SELECT id FROM users WHERE id=? FOR UPDATE',[$a->user['id']]);if(!DB::one('SELECT id FROM materials WHERE id=? AND deleted_at IS NULL FOR UPDATE',[$id])){throw new ApiError(404,'NOT_FOUND','Материал не найден');}