 new ApiError(404,'NOT_FOUND','Материал не найден');}$after=DriveLibrary::cursor($r->body['after']??'');$files=$r->body['files']??[];if(!is_array($files)||count($files)>20||count(array_filter($files,static fn($file)=>Input::id($file)!==null))!==count($files)){throw new ApiError(422,'DRIVE_ACTION','Некорректный список файлов');}return DriveLibrary::execute(material:$id,phase:$phase,after:$after,files:array_values($files));}public function validateFile(Auth$a,string$id):array{$file=DB::one("SELECT * FROM material_files WHERE id=? AND scan_status IN ('quarantined','local_unscanned')",[$id]);if(!$file)throw new ApiError(404,'NOT_FOUND','Файл для проверки не найден');$material=Access::material($a,$file['material_id'],true);$path=Config::storage().'/files/'.$file['storage_key'];$status='rejected';if(!is_file($path))throw new ApiError(503,'STORAGE','Оригинал файла недоступен');if(hash_equals($file['checksum_sha256'],hash_file('sha256',$path)?:'')){$status='clean';}if(!DB::run("UPDATE material_files SET scan_status=?,mime_type=?
